/**
 * Account management > New POS account: the administrator creates a business account (sign-in, profile and an empty POS with the business
 * type already chosen). A blank password is generated by the server and shown once, together with the owner's first PIN.
 */
import { useState } from "react";
import { ADMIN_BUSINESS_TYPE_OPTIONS } from "../config/presets";
import { adminApi } from "./adminApi";
import { businessTypeLabel } from "./BusinessTypeTab";

const BLANK = { name: "", business: "", email: "", mobile: "", businessType: "restaurant", password: "" };

export function NewAccountPanel({ onClose, onCreated, ui }) {
	const [form, setForm] = useState(BLANK);
	const [busy, setBusy] = useState(false);
	const [made, setMade] = useState(null);
	const set = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));

	const create = async (e) => {
		e.preventDefault();
		setBusy(true);
		try {
			const r = await adminApi({ action: "createAccount", ...form });
			setMade({ ...r, password: r.password || form.password });
			onCreated();
		} catch (err) {
			await ui.alert(err.message);
		} finally {
			setBusy(false);
		}
	};
	const copy = async () => {
		const text = `Business: ${made.account.business}\nSign-in e-mail: ${made.account.email}\nPassword: ${made.password}\nOwner PIN: ${made.ownerPin}`;
		try {
			await navigator.clipboard.writeText(text);
			ui.notice("Sign-in details copied.");
		} catch {
			await ui.alert(text);
		}
	};

	if (made)
		return (
			<section className="panel" id="new-account-done" aria-live="polite">
				<div className="panel-head">
					<div>
						<div className="panel-title">Account created</div>
						<div className="muted">Give these sign-in details to the business owner. The password is shown only now.</div>
					</div>
				</div>
				<div className="modal-body">
					<dl className="admin-dl">
						<dt>Business</dt><dd>{made.account.business}</dd>
						<dt>Sign-in e-mail</dt><dd>{made.account.email}</dd>
						<dt>Password</dt><dd><code>{made.password}</code>{made.generated ? " (generated)" : ""}</dd>
						<dt>Owner PIN</dt><dd><code>{made.ownerPin}</code> (the owner should change it after signing in)</dd>
					</dl>
					<div className="tools" style={{ marginTop: 12 }}>
						<button type="button" className="btn out" onClick={copy}>Copy details</button>
						<button type="button" className="btn gold" onClick={onClose}>Done</button>
					</div>
				</div>
			</section>
		);

	return (
		<section className="panel" id="new-account">
			<div className="panel-head">
				<div>
					<div className="panel-title">New POS account</div>
					<div className="muted">Creates the business sign-in and an empty POS. It starts on the free trial.</div>
				</div>
			</div>
			<form className="modal-body" onSubmit={create}>
				<div className="form-grid">
					<div className="field">
						<label htmlFor="na-business">Business name</label>
						<input id="na-business" className="input" required minLength={2} maxLength={80} autoComplete="off" autoFocus value={form.business} onChange={set("business")} />
					</div>
					<div className="field">
						<label htmlFor="na-name">Owner's name</label>
						<input id="na-name" className="input" required minLength={2} maxLength={50} autoComplete="off" value={form.name} onChange={set("name")} />
					</div>
					<div className="field">
						<label htmlFor="na-email">Sign-in e-mail</label>
						<input id="na-email" className="input" type="email" required maxLength={254} autoComplete="off" value={form.email} onChange={set("email")} />
					</div>
					<div className="field">
						<label htmlFor="na-mobile">Mobile (optional)</label>
						<input id="na-mobile" className="input" type="tel" maxLength={20} autoComplete="off" value={form.mobile} onChange={set("mobile")} />
					</div>
					<div className="field">
						<label htmlFor="na-type">Business type</label>
						<select id="na-type" className="input" value={form.businessType} onChange={set("businessType")}>
							{ADMIN_BUSINESS_TYPE_OPTIONS.map((t) => (
								<option key={t} value={t}>{businessTypeLabel(t)}</option>
							))}
						</select>
					</div>
					<div className="field">
						<label htmlFor="na-password">Password</label>
						<input id="na-password" className="input" type="password" minLength={8} maxLength={256} autoComplete="new-password" placeholder="Leave blank to generate one" value={form.password} onChange={set("password")} />
					</div>
				</div>
				<div className="tools" style={{ marginTop: 14 }}>
					<button type="submit" className="btn gold" id="create-account" disabled={busy}>{busy ? "Creating…" : "Create account"}</button>
					<button type="button" className="btn out" disabled={busy} onClick={onClose}>Cancel</button>
				</div>
			</form>
		</section>
	);
}
